import {noteName,isBlack} from './engine.js';

export const MAJOR=[0,2,4,5,7,9,11];
export const CHORDS={C:[60,64,67],Dm:[62,65,69],Em:[64,67,71],F:[60,65,69],G:[59,62,67],Am:[60,64,69]};
const roots={C:48,Dm:50,Em:52,F:41,G:43,Am:45};
const chordNames={C:'C major',Dm:'D minor',Em:'E minor',F:'F major',G:'G major',Am:'A minor'};
const progressions=[{name:'The familiar four',chords:['C','G','Am','F'],mood:'A versatile starting point for pop-style songs.'},{name:'A little cinematic',chords:['Am','F','C','G'],mood:'A gentle minor-key starting point.'},{name:'A classic turn',chords:['C','Am','F','G'],mood:'A warm, familiar circle back to C.'}];
const fingers=[1,2,3,4,5],scaleFingers=[1,2,3,1,2,3,4,5,4,3,2,1,3,2,1];
const makeNotes=(pitches,hand='right',fingerNumbers=fingers,beat=.75)=>pitches.map((pitch,i)=>({id:i,pitch,time:i*beat,duration:beat*.72,hand,finger:fingerNumbers[i%fingerNumbers.length]}));
const lesson=(id,title,description,notes,bpm=80)=>({id:'lesson-'+id,title,artist:'Piano Club · Beginner foundations',label:'Original learning exercise',description,notes,bpm,color:'#add8c4',difficulty:1});
export function basicDrills(){
  const five=[60,62,64,65,67,65,64,62,60];
  const right=makeNotes(five,'right',[1,2,3,4,5,4,3,2,1]);
  const left=makeNotes(five.map(n=>n-12),'left',[5,4,3,2,1,2,3,4,5]);
  const major=[60,62,64,65,67,69,71,72,71,69,67,65,64,62,60];
  const contrary=[];for(let i=0;i<9;i++){const at=i<5?i:8-i;contrary.push({pitch:60+[0,2,4,5,7][at],time:i*.85,duration:.6,hand:'right',finger:at+1});contrary.push({pitch:60-[0,1,3,5,7][at],time:i*.85,duration:.6,hand:'left',finger:at+1});}
  return [
    lesson('right-five','Your first five notes','Right thumb on C4. Keep each finger over its own key. Play C–D–E–F–G, then come back. Keep your touch light.',right),
    lesson('left-five','Let the left hand join','Left little finger on C3, thumb on G3. Play C–D–E–F–G and back. Notice that the finger numbers run the opposite way.',left),
    lesson('finger-walk','A little finger independence','C–E–D–F–E–G–F–D–C. Keep the fingers close to the keys. Start slowly and aim for an even sound.',makeNotes([60,64,62,65,64,67,65,62,60],'right',[1,3,2,4,3,5,4,2,1])),
    lesson('c-scale','Your first C-major scale','Right hand: C1 D2 E3, pass your thumb under to F1, then G2 A3 B4 C5. Come down in reverse. Keep the crossing relaxed.',makeNotes(major,'right',scaleFingers)),
    lesson('contrary','Hands moving apart','Start both thumbs on middle C, then move in opposite directions. Use Chords mode to play simultaneously, or learn each hand separately first.',contrary.map((n,i)=>({...n,id:i})),70),
    lesson('broken-am','Turn a chord into a melody','Right hand: A3–C4–E4–C4. Fingers 1–2–5–2. These are the same three notes as A minor, played one at a time.',makeNotes([57,60,64,60,57,60,64,60,57,60,64,60],'right',[1,2,5,2]),80)
  ];
}
export function chordExercise(names,pattern='broken'){
  const notes=[];let id=0;
  names.forEach((name,bar)=>{
    const pitches=CHORDS[name],base=bar*3;
    notes.push({id:id++,pitch:roots[name],time:base,duration:2.5,hand:'left',finger:5});
    if(pattern==='together')pitches.forEach((pitch,i)=>notes.push({id:id++,pitch,time:base,duration:2.4,hand:'right',finger:[1,3,5][i]}));
    else {const order=pattern==='rolling'?[0,1,2,1,0,1,2,1]:[0,1,2,0,1,2];order.forEach((at,i)=>notes.push({id:id++,pitch:pitches[at],time:base+i*3/order.length,duration:.3,hand:'right',finger:[1,3,5][at]}));}
  });
  notes.sort((a,b)=>a.time-b.time);
  return lesson('chords-'+names.join('-')+'-'+pattern,names.join(' → '),pattern==='together'?'Left hand plays the root. Right hand plays the three chord notes together.':'Left hand plays the root. Right hand breaks each chord into a flowing pattern.',notes,80);
}
function keyboardSvg(active,labelled=true){
  const width=350,w=50,blackIndices=[1,3,6,8,10];let wi=0;const keys=[];
  for(let n=60;n<=71;n++){if(isBlack(n))continue;const x=wi++*w;keys.push(`<rect x="${x}" y="2" width="48" height="128" rx="5" fill="${active.includes(n)?'#fc795e':'#fffdf5'}" stroke="#bfc6b9"/>${labelled?`<text x="${x+24}" y="114" text-anchor="middle" fill="#495c50" font-size="14">${noteName(n).replace(/\d/,'')}</text>`:''}`);}
  wi=0;for(let n=60;n<=71;n++){if(!isBlack(n)){wi++;continue;}keys.push(`<rect x="${wi*w-15}" y="2" width="28" height="78" rx="4" fill="${active.includes(n)?'#fc795e':'#273532'}"/>`);}
  return `<svg class="lesson-keyboard" viewBox="0 0 ${width} 134" role="img" aria-label="${labelled?'Highlighted piano notes':'One highlighted white piano key'}">${keys.join('')}</svg>`;
}
function staffSvg(note){const natural=[60,62,64,65,67,69,71,72,74,76,77,79],index=natural.indexOf(note),y=108-index*8;return `<svg class="quiz-staff" viewBox="0 0 350 145" role="img" aria-label="Treble staff with a note to identify">${[28,44,60,76,92].map(y=>`<path d="M20 ${y}H330"/>`).join('')}<text x="32" y="99" font-size="86" fill="#293b31">𝄞</text>${note===60?'<path d="M182 108h37"/>':''}<ellipse cx="200" cy="${y}" rx="11" ry="8" fill="#e5755c" stroke="none" transform="rotate(-18 200 ${y})"/><path d="M210 ${y}v-43" stroke="#e5755c" stroke-width="2"/></svg>`;}

export function initLearning({openPlayer,audio,stop,toast}){
  const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
  let quizMode='keys',quizNote=60,quizLocked=false,quizCorrect=0,quizTries=0,quizStreak=0,chord='C',progression=0,pattern='broken',jamTimer=null,jamStep=0;
  try{const p=JSON.parse(localStorage.getItem('piano-learning')||'{}');quizCorrect=p.correct||0;quizTries=p.tries||0;}catch{}
  const section=document.createElement('section');section.id='learning';section.hidden=true;
  section.innerHTML=`<div class="learn-heading"><div><span class="eyebrow">A LITTLE KNOW-HOW. A LOT MORE MUSIC.</span><h1>Start small.<br><em>Sound good.</em></h1><p>You don’t need piano school to begin.<br>Find a note, build a chord, make something yours.</p></div><div class="learn-sticker">C + E + G<br><strong>you made<br>a chord.</strong></div></div><div class="learn-tabs" role="tablist" aria-label="Piano learning topics"><button role="tab" aria-selected="true" data-learn-tab="notes">01 · Know your notes</button><button role="tab" aria-selected="false" data-learn-tab="drills">02 · Find your fingers</button><button role="tab" aria-selected="false" data-learn-tab="chords">03 · Build a chord</button><button role="tab" aria-selected="false" data-learn-tab="improv">04 · Make it yours</button></div>
  <div class="learn-panel" data-learn-panel="notes" role="tabpanel"><div class="lesson-intro"><span class="eyebrow">START HERE · NOTE NAMES</span><h2>Find two black keys.<br>C is just to their left.</h2><p>The white notes repeat: <strong>C D E F G A B</strong>, then C again. Find a group of two black keys. The white key immediately to the left is C. F is immediately left of a group of three black keys.</p>${keyboardSvg([60])}<div class="callout">Your Yamaha has 61 keys. The far-left white key is C2; middle C is C4. The number tells you which octave. A sharp (♯) moves one key to the right, including black keys; a flat (♭) moves one key left.</div><details><summary>What about notes on a staff?</summary><p>On the treble staff, the five lines from bottom to top are <b>E G B D F</b>. The four spaces spell <b>F A C E</b>. Middle C sits on a short extra line below the staff.</p><p>The bass staff is often used for the left hand: lines <b>G B D F A</b>, spaces <b>A C E G</b>, bottom to top.</p></details></div><div class="quiz-card"><span class="eyebrow">A TINY DAILY CHALLENGE</span><h3>Name that note.</h3><div class="quiz-switch"><button data-quiz-mode="keys" class="selected">On the keyboard</button><button data-quiz-mode="staff">On the staff</button></div><div id="quiz-picture"></div><div id="quiz-answers" class="quiz-answers">${['C','D','E','F','G','A','B'].map(n=>`<button data-answer="${n}">${n}</button>`).join('')}</div><p id="quiz-feedback" role="status">Which note is highlighted?</p><button class="button dark" id="quiz-next" hidden>Next note →</button><div id="quiz-score" class="quiz-score"></div></div></div>
  <div class="learn-panel" data-learn-panel="drills" role="tabpanel" hidden><div class="lesson-intro"><span class="eyebrow">5 MINUTES IS A GOOD START</span><h2>Build a little muscle memory.</h2><p>Start with the right hand, then the left. Keep your fingers curved and your touch light. Repeat a short section seven times cleanly before making it faster.</p><div class="callout">Finger numbers: <b>1 thumb · 2 index · 3 middle · 4 ring · 5 little.</b> The numbers are the same on both hands.</div></div><div id="drill-grid" class="drill-grid"></div></div>
  <div class="learn-panel" data-learn-panel="chords" role="tabpanel" hidden><div class="lesson-intro"><span class="eyebrow">THREE NOTES, A WHOLE NEW SOUND</span><h2>Meet the chord.</h2><p>A basic chord, or triad, has three notes: a <b>root, a third, and a fifth</b>. C major is C–E–G. C minor changes just E to E♭. The third gives a chord its major or minor character.</p><p>These six chords belong to C major. Some use <b>inversions</b>: the same three note names in a different order, so your hand moves less.</p><div class="chord-choices">${Object.keys(CHORDS).map(name=>`<button data-chord="${name}">${name}</button>`).join('')}</div><div id="chord-card" class="chord-card"></div></div><div class="progression-card"><span class="eyebrow">PUT A FEW TOGETHER</span><h3>A chord progression.</h3><label>Choose a progression<select id="progression-choice">${progressions.map((p,i)=>`<option value="${i}">${p.name} · ${p.chords.join(' – ')}</option>`).join('')}</select></label><div id="progression-chips"></div><p id="progression-mood"></p><label>How to play it<select id="chord-pattern"><option value="broken">Broken · low–middle–high</option><option value="rolling">Rolling · up and back</option><option value="together">Together · block chords</option></select></label><p class="small-note">A broken chord plays the same notes one after another. An arpeggio often carries that pattern across more octaves.</p><div class="detail-actions"><button id="progression-practice" class="button dark">Practice the pattern</button><button id="progression-demo" class="button outline">Hear it first</button></div></div></div>
  <div class="learn-panel" data-learn-panel="improv" role="tabpanel" hidden><div class="lesson-intro"><span class="eyebrow">YOUR FIRST LITTLE IMPROVISATION</span><h2>Less guessing.<br>More listening.</h2><p>Start with <b>A minor → F → C → G</b>. Play one chord slowly with the left hand, or break it into a pattern. With the right hand, explore just these five notes:</p><div class="improv-notes">${[69,72,74,76,79].map(n=>`<button data-jam-note="${n}" aria-label="Hear ${noteName(n)}">${noteName(n)}<small>${['A','C','D','E','G'].indexOf(noteName(n).replace(/\d/,''))+1}</small></button>`).join('')}</div><p><b>A C D E G</b> make up the A-minor pentatonic scale. Start with two or three notes. Leave a pause. Repeat your little idea, then change its last note.</p><div class="callout">For a settled sound, land on a note in the current chord. On <b>Am: A, C or E</b>. On <b>F: F, A or C</b>. On <b>C: C, E or G</b>. On <b>G: G, B or D</b>. F and B are useful extra notes beyond your five-note starting set.</div></div><div class="jam-card"><span class="eyebrow">YOUR TINY BACKING BAND</span><h3>Play a little. Listen a little.</h3><p>This is free play: there’s no score to pass and no mistake counter.</p><div class="jam-current"><span>NOW PLAYING</span><strong id="jam-chord">Am</strong><small id="jam-hint">A · C · E</small></div><button id="jam-toggle" class="button dark">Start gentle backing</button><label class="jam-speed">Backing tempo <strong id="jam-bpm">72 BPM</strong><input id="jam-tempo" type="range" min="40" max="100" value="72" step="2"></label><p class="small-note">Play on your own keyboard, or tap the five notes here. The backing uses your phone’s speaker. Microphone judging is off in this free-play lab.</p><button id="improv-study" class="text-button">Teach me the left-hand pattern →</button></div></div>`;
  $('.library-main').append(section);
  const nav=document.createElement('button');nav.id='learn-nav';nav.textContent='Learn piano';$('#guide-nav').before(nav);
  function showLearning(){document.body.classList.add('learning-view');section.hidden=false;$('#library-nav').classList.remove('nav-active');nav.classList.add('nav-active');window.scrollTo(0,0);}
  function hideLearning(){stopJam();document.body.classList.remove('learning-view');section.hidden=true;nav.classList.remove('nav-active');$('#library-nav').classList.add('nav-active');}
  nav.onclick=showLearning;$('#library-nav').addEventListener('click',hideLearning);$('.brand').addEventListener('click',hideLearning);
  $$('[data-learn-tab]').forEach(b=>b.onclick=()=>{stopJam();$$('[data-learn-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));$$('[data-learn-panel]').forEach(p=>p.hidden=p.dataset.learnPanel!==b.dataset.learnTab);});
  function quiz(){quizLocked=false;const candidates=quizMode==='keys'?[60,62,64,65,67,69,71]:[60,62,64,65,67,69,71,72,74,76,77];const others=candidates.filter(n=>n!==quizNote);quizNote=others[Math.floor(Math.random()*others.length)];$('#quiz-picture').innerHTML=quizMode==='keys'?keyboardSvg([quizNote],false):staffSvg(quizNote);$('#quiz-feedback').textContent=quizMode==='keys'?'Which note is highlighted?':'What is this note’s letter name?';$('#quiz-next').hidden=true;$$('[data-answer]').forEach(b=>{b.disabled=false;b.classList.remove('correct','incorrect');});$('#quiz-score').textContent=`${quizCorrect} correct / ${quizTries} attempts · ${quizStreak} in a row`;
  }
  $$('[data-quiz-mode]').forEach(b=>b.onclick=()=>{quizMode=b.dataset.quizMode;$$('[data-quiz-mode]').forEach(x=>x.classList.toggle('selected',x===b));quiz();});
  $$('[data-answer]').forEach(b=>b.onclick=()=>{if(quizLocked)return;quizLocked=true;quizTries++;const answer=noteName(quizNote).replace(/\d/g,''),correct=b.dataset.answer===answer;if(correct){quizCorrect++;quizStreak++;b.classList.add('correct');$('#quiz-feedback').textContent=`Yes — ${answer}! ${quizMode==='keys'?'Find it on your Yamaha, too.':'Notice its position on the staff.'}`;}else{quizStreak=0;b.classList.add('incorrect');$(`[data-answer="${answer}"]`).classList.add('correct');$('#quiz-feedback').textContent=`That’s ${answer}. Take a moment to look, then try another.`;}$$('[data-answer]').forEach(x=>x.disabled=true);$('#quiz-next').hidden=false;$('#quiz-score').textContent=`${quizCorrect} correct / ${quizTries} attempts · ${quizStreak} in a row`;try{localStorage.setItem('piano-learning',JSON.stringify({correct:quizCorrect,tries:quizTries}));}catch{};});
  $('#quiz-next').onclick=quiz;quiz();
  const drills=basicDrills();$('#drill-grid').innerHTML=drills.map((d,i)=>`<article class="drill-card"><span class="drill-number">0${i+1}</span><h3>${d.title}</h3><p>${d.description}</p><button class="text-button" data-drill="${i}">Practice with 7× →</button></article>`).join('');
  $$('[data-drill]').forEach(b=>b.onclick=()=>{stopJam();openPlayer(drills[Number(b.dataset.drill)],'seven');});
  const hear=async pitches=>{try{await audio.unlock();pitches.forEach(p=>audio.play(p,.95,.15/Math.sqrt(pitches.length)));}catch(e){toast(e.message);}};
  function chordCard(){const notes=CHORDS[chord];const inv=notes[0]%12!==roots[chord]%12;$('#chord-card').innerHTML=`<span class="eyebrow">${inv?'A COMFORTABLE INVERSION':'ROOT POSITION'}</span><h3>${chordNames[chord]}</h3><strong class="chord-note-names">${notes.map(noteName).join(' · ')}</strong><p>Right hand fingers: <b>1 · 3 · 5</b>. Left hand root: <b>${noteName(roots[chord])}</b>.<br>${inv?'Same chord tones, reordered to keep your hand nearby.':'Play the three notes together, then one at a time.'}</p><div class="detail-actions"><button class="button dark" id="hear-chord">Hear this chord</button><button class="button outline" id="practice-chord">Learn its notes</button></div>`;$$('[data-chord]').forEach(b=>b.classList.toggle('selected',b.dataset.chord===chord));$('#hear-chord').onclick=()=>hear(notes);$('#practice-chord').onclick=()=>openPlayer(chordExercise([chord,chord],'broken'),'seven');}
  $$('[data-chord]').forEach(b=>b.onclick=()=>{chord=b.dataset.chord;chordCard();});chordCard();
  function progressionCard(){const p=progressions[progression];$('#progression-chips').innerHTML=p.chords.map(n=>`<span>${n}</span>`).join('<i>→</i>');$('#progression-mood').textContent=p.mood;}
  $('#progression-choice').onchange=e=>{progression=Number(e.target.value);progressionCard();};$('#chord-pattern').onchange=e=>pattern=e.target.value;
  $('#progression-practice').onclick=()=>openPlayer(chordExercise(progressions[progression].chords,pattern),'seven');$('#progression-demo').onclick=()=>openPlayer(chordExercise(progressions[progression].chords,pattern),'watch');progressionCard();
  function stopJam(){clearTimeout(jamTimer);jamTimer=null;$('#jam-toggle').textContent='Start gentle backing';}
  function jamTick(){const names=['Am','F','C','G'],at=jamStep%8,name=names[Math.floor(jamStep/8)%4],root=roots[name];const triad=CHORDS[name];const pitches=[root,root+7,root+(name.endsWith('m')?3:4),root+7];audio.play(pitches[at%4],.55,.12);$('#jam-chord').textContent=name;$('#jam-hint').textContent=triad.map(n=>noteName(n).replace(/\d/,'' )).join(' · ');jamStep++;jamTimer=setTimeout(jamTick,30000/Number($('#jam-tempo').value));}
  $('#jam-toggle').onclick=async()=>{if(jamTimer){stopJam();audio.stopVoices();return;}try{stop();await audio.unlock();jamStep=0;$('#jam-toggle').textContent='Stop backing';jamTick();}catch(e){toast(e.message);}};
  $('#jam-tempo').oninput=e=>$('#jam-bpm').textContent=e.target.value+' BPM';$$('[data-jam-note]').forEach(b=>b.onclick=()=>hear([Number(b.dataset.jamNote)]));
  $('#improv-study').onclick=()=>{stopJam();const notes=[];let id=0;['Am','F','C','G'].forEach((n,bar)=>[roots[n],roots[n]+7,roots[n]+(n.endsWith('m')?3:4),roots[n]+7].forEach((pitch,i)=>notes.push({id:id++,pitch,time:bar*3+i*.75,duration:.5,hand:'left',finger:[5,1,3,1][i]})));openPlayer(lesson('improv-left','A gentle left-hand pattern','Repeat the four-note pattern for each chord. Once comfortable, let your right hand explore A C D E G.',notes),'seven');};
  document.addEventListener('piano:stop-extra-audio',stopJam);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopJam();});
}
